INSERT INTO "dynasties" ("id","name","alt_names","ethnicity","scope","region","start_year","start_month","start_day","start_confidence","end_year","end_month","end_day","end_confidence","start_abs","end_abs","color_token","parent_id","group_id","note") VALUES ('gaogouli','高句丽','["高句丽","高句骊","高丽"]','高句丽','cn','east_asia',-37,1,NULL,'year',668,1,NULL,'year',-432,8016,'ochre',NULL,NULL,'前37年朱蒙建国；668年唐将薛仁贵等灭之，宝藏王被俘。');
INSERT INTO "dynasties" ("id","name","alt_names","ethnicity","scope","region","start_year","start_month","start_day","start_confidence","end_year","end_month","end_day","end_confidence","start_abs","end_abs","color_token","parent_id","group_id","note") VALUES ('huihu','回鹘','["回鹘","回纥","回纥汗国"]','回鹘','cn','east_asia',744,1,NULL,'year',840,1,NULL,'year',8928,10080,'ochre',NULL,NULL,'744年骨力裴罗建国；840年黠戛斯攻破牙帐，㕎馺可汗被杀，漠北汗国终结。');
INSERT INTO "dynasties" ("id","name","alt_names","ethnicity","scope","region","start_year","start_month","start_day","start_confidence","end_year","end_month","end_day","end_confidence","start_abs","end_abs","color_token","parent_id","group_id","note") VALUES ('tubo','吐蕃','["大蕃","吐番"]','藏','cn','east_asia',618,1,NULL,'year',842,1,NULL,'year',7416,10104,'ochre',NULL,NULL,'南日松赞在7世纪初扩展雅隆王室的势力，松赞干布继位后平定内乱、兼并周边诸部，以逻些为政治中心。吐蕃此后扩张至青海、河西和中亚部分地区，与唐朝时有战争及和亲、会盟；9世纪中叶朗达玛被杀后，王室争位与地方分裂加剧，帝国解体。');
INSERT INTO "dynasties" ("id","name","alt_names","ethnicity","scope","region","start_year","start_month","start_day","start_confidence","end_year","end_month","end_day","end_confidence","start_abs","end_abs","color_token","parent_id","group_id","note") VALUES ('tuyuhun','吐谷浑','["吐谷浑","吐谷浑汗国","白兰"]','慕容鲜卑','cn','east_asia',329,1,NULL,'year',663,1,NULL,'year',3948,7956,'ochre',NULL,NULL,'慕容吐谷浑在西晋时期率部西迁，其后裔在青海一带建立统治。叶延以祖名吐谷浑作为族号、国号，政权在河湟及青海草原延续；663年吐蕃击败吐谷浑，诺曷钵与弘化公主奔唐，王室此后仍以唐朝属部身份活动。');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('achen','阿豺','tuyuhun','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','阿豺为吐谷浑首领，传世记载称其曾遣使与南朝交往，并在临终时以折箭告诫诸弟团结。其弟慕璝继立，吐谷浑在此后继续与北魏、西秦等政权周旋。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/阿豺"},{"label":"《旧唐书·吐谷浑传》研究所引史料（山西大学学位论文）","url":"https://ygx.sxu.edu.cn/db/学位/D01117545.pdf"}]','威王',NULL,'白兰王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('aidengli-kehan','胡特勤','huihu','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["可汗","君主"]','昭礼可汗从子，唐封彰信可汗。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/彰信可汗"}]',NULL,NULL,'彰信可汗','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('ancang-wang','安藏王','gaogouli','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','安藏王名兴安，为文咨王之子。其在位时高句丽与南朝梁、北魏均保持册封往来；死后无子，由弟安原王继位。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/安藏王"},{"label":"《三国史记·高句丽国本纪》（中国哲学书电子化计划）","url":"https://ctext.org/wiki.pl?chapter=285115&if=en&remap=gb"}]',NULL,NULL,'安藏王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('anyuan-kehan','保义','huihu','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["可汗","君主"]','本名失载，硖跌氏，怀信可汗庶长子，唐封保义可汗。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/保义可汗"}]',NULL,NULL,'保义可汗','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('anyuan-wang','安原王','gaogouli','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','安原王名宝延，是安藏王之弟。其在位时期新罗、百济围绕汉江流域竞争加剧，王室继承亦出现争议；死后由阳原王继位。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/安原王"},{"label":"《三国史记·高句丽国本纪》（中国哲学书电子化计划）","url":"https://ctext.org/wiki.pl?chapter=285115&if=en&remap=gb"}]',NULL,NULL,'安原王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('baozang-wang','宝藏王','gaogouli','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','宝藏王是高句丽末代君主，由渊盖苏文拥立。唐与新罗联合攻灭高句丽后，他于668年被俘至唐；高句丽政权结束，部分遗民后来建立渤海。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/宝藏王"},{"label":"《三国史记·高句丽国本纪》（中国哲学书电子化计划）","url":"https://ctext.org/wiki.pl?chapter=285115&if=en&remap=gb"}]',NULL,NULL,'宝藏王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('changsheng-wang','长寿王','gaogouli','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','长寿王名巨连，为广开土王之子，在位近八十年。其将都城迁至平壤并继续向南扩张，高句丽由此进入疆域与国势的高峰期。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/长寿王"},{"label":"《三国史记·高句丽国本纪》（中国哲学书电子化计划）","url":"https://ctext.org/wiki.pl?chapter=285115&if=en&remap=gb"}]',NULL,NULL,'长寿王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('cida-wang','次大王','gaogouli','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','次大王名遂成，是太祖王之弟。太祖王年老时他掌握政权并继位；高句丽史书称其晚年遭臣下弑杀，王位转由新大王承接。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/次大王"},{"label":"《三国史记·高句丽国本纪》（中国哲学书电子化计划）","url":"https://ctext.org/wiki.pl?chapter=285115&if=en&remap=gb"}]',NULL,NULL,'次大王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('daewuseong','大武神王','gaogouli','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','大武神王名无恤，为琉璃明王之子。其在位期间高句丽向扶余扩张，并与乐浪等势力冲突；传世史书将这一阶段视为早期高句丽扩展的重要时期。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/大武神王"},{"label":"《三国史记·高句丽国本纪》（中国哲学书电子化计划）","url":"https://ctext.org/wiki.pl?chapter=285115&if=en&remap=gb"}]',NULL,NULL,'大武神王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('dongchuan-wang','东川王','gaogouli','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','东川王名忧位居，为山上王之子。魏将毌丘俭于244年进攻高句丽并攻入丸都，东川王出逃至东沃沮；魏军撤退后他重建国都。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/东川王"},{"label":"《三国史记·高句丽国本纪》（中国哲学书电子化计划）","url":"https://ctext.org/wiki.pl?chapter=285115&if=en&remap=gb"}]',NULL,NULL,'东川王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('dusong-mangje','杜松芒赞','tubo','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','吐蕃赞普，亦称赤都松赞、杜松芒波杰。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/杜松芒赞"}]',NULL,NULL,'赞普','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('duyihou','度易侯','tuyuhun','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','河南王，吐谷浑中期君主。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/度易侯"}]',NULL,NULL,'河南王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('enzhen-kehan','遏捻特勤','huihu','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["可汗","君主"]','唐封遏捻可汗，846—848年在位，回鹘南迁时期末代可汗。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/遏捻可汗"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('fengcheng-kehan','多逻斯','huihu','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["可汗","君主"]','顿莫贺达干之子，唐封忠贞可汗，在位仅一年。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/忠贞可汗"}]',NULL,NULL,'忠贞可汗','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('fengshang-wang','烽上王','gaogouli','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','烽上王名相夫，是西川王之侄。高句丽本纪记他猜忌大臣、诛杀重臣；301年大臣反叛将其废黜，他自杀，王位交给美川王。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/烽上王"},{"label":"《三国史记·高句丽国本纪》（中国哲学书电子化计划）","url":"https://ctext.org/wiki.pl?chapter=285115&if=en&remap=gb"}]',NULL,NULL,'烽上王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('fengyi-kehan','滕里','huihu','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["可汗","君主"]','本名失载，怀信可汗之后，唐封滕里可汗。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/滕里可汗"}]',NULL,NULL,'滕里可汗','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('fulianchou','伏连筹','tuyuhun','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','伏连筹为吐谷浑首领，传世年表称其统治约五十年。其死后由夸吕继位；《北史》等记载表明吐谷浑继续控制青海周边并与北魏保持政治往来。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/伏连筹"},{"label":"《旧唐书·吐谷浑传》研究所引史料（山西大学学位论文）","url":"https://ygx.sxu.edu.cn/db/学位/D01117545.pdf"}]',NULL,NULL,'可汗','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('fuyun','伏允','tuyuhun','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','伏允是夸吕之子，继位后与隋、唐反复交战。唐军635年进攻吐谷浑时，他出逃并最终被部下杀死；其死后吐谷浑一度受唐册立的慕容顺控制。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/伏允"},{"label":"《旧唐书·吐谷浑传》研究所引史料（山西大学学位论文）","url":"https://ygx.sxu.edu.cn/db/学位/D01117545.pdf"}]',NULL,NULL,'步萨钵可汗','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('gao-zhumeng','高朱蒙','gaogouli','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','高朱蒙即朱蒙，传说为扶余出身，后来南下至卒本建立高句丽。其建国故事见于《三国史记》与中国史籍，早期世系带有明显的王权起源传说色彩。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/朱蒙"},{"label":"《三国史记·高句丽国本纪》（中国哲学书电子化计划）","url":"https://ctext.org/wiki.pl?chapter=285115&if=en&remap=gb"}]',NULL,NULL,'东明圣王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('guangkaitu-wang','广开土王','gaogouli','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','广开土王名谈德，是故国壤王之子。其在位期间向百济、扶余及辽东扩张；现存好太王碑记录其征战与王权叙事，是研究高句丽的重要一手材料。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/广开土王"},{"label":"《三国史记·高句丽国本纪》（中国哲学书电子化计划）","url":"https://ctext.org/wiki.pl?chapter=285115&if=en&remap=gb"}]',NULL,NULL,'广开土王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('guguo-chuan-wang','故国川王','gaogouli','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','故国川王名男武，承新大王之后在位。传统记载称他任用乙巴素为国相、推行赈济贫民的“真大法”；死后王位由弟山上王继承。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/故国川王"},{"label":"《三国史记·高句丽国本纪》（中国哲学书电子化计划）","url":"https://ctext.org/wiki.pl?chapter=285115&if=en&remap=gb"}]',NULL,NULL,'故国川王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('guguo-rang-wang','故国壤王','gaogouli','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','故国壤王名伊连，是小兽林王之弟、广开土王之父。他继位后继续整顿高句丽政权，为儿子扩张国势奠定基础；其后由广开土王即位。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/故国壤王"},{"label":"《三国史记·高句丽国本纪》（中国哲学书电子化计划）","url":"https://ctext.org/wiki.pl?chapter=285115&if=en&remap=gb"}]',NULL,NULL,'故国壤王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('guguo-yuan-wang','故国原王','gaogouli','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','故国原王名斯由，为美川王之子。前燕曾攻入高句丽都城并掳走其母；371年百济近肖古王北伐时，故国原王战死于平壤城下。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/故国原王"},{"label":"《三国史记·高句丽国本纪》（中国哲学书电子化计划）","url":"https://ctext.org/wiki.pl?chapter=285115&if=en&remap=gb"}]',NULL,NULL,'故国原王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('guli-peiluo','骨力裴罗','huihu','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["可汗","君主"]','回纥药罗葛氏首领。742年联合拔悉密、葛逻禄反抗后突厥，先推拔悉密首领为可汗，自任叶护；744年又与葛逻禄击败拔悉密，自立为可汗，建立回纥汗国，获唐封怀仁可汗。745年击败后突厥末代白眉可汗，控制其故地。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/骨力裴罗"}]',NULL,NULL,'怀仁可汗','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('huairen-kehan','顿莫贺达干','huihu','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["可汗","君主"]','杀移地健自立，唐封长寿天亲可汗。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/顿莫贺达干"}]',NULL,NULL,'长寿天亲可汗','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('huaixin-kehan','骨咄禄','huihu','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["可汗","君主"]','阿跌氏，唐封怀信可汗，阿啜之后继统。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/怀信可汗"}]',NULL,NULL,'怀信可汗','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('jieyu-jiasi','阿啜','huihu','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["可汗","君主"]','多逻斯之弟，唐封奉诚可汗。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/奉诚可汗"}]',NULL,NULL,'奉诚可汗','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('kasa-kehan','葛萨','huihu','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["可汗","君主"]','亦称㕎馺特勤，篡位，唐封㕎馺可汗，840年牙帐陷落时被杀。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/㕎馺可汗"}]',NULL,NULL,'㕎馺可汗','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('kuailv','夸吕','tuyuhun','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','夸吕承伏连筹之后为吐谷浑可汗，统治期间与隋发生长期冲突。隋炀帝曾大举西征，吐谷浑部众一度离散；隋末政局变化后夸吕恢复对青海的控制。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/夸吕"},{"label":"《旧唐书·吐谷浑传》研究所引史料（山西大学学位论文）","url":"https://ygx.sxu.edu.cn/db/学位/D01117545.pdf"}]',NULL,NULL,'可汗','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('lang-darma','朗达玛','tubo','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','朗达玛是吐蕃末代赞普。传统叙事称他推行限制佛教的政策，842年被僧人拉隆贝吉多杰刺杀；其死后王室争位，吐蕃帝国迅速分裂。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/朗达玛"},{"label":"《新唐书·吐蕃传》（中国哲学书电子化计划）","url":"https://ctext.org/wiki.pl?chapter=496263&if=gb&remap=gb"}]',NULL,NULL,'赞普','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('liuli-ming-wang','琉璃明王','gaogouli','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','琉璃明王名类利，是朱蒙之子。朱蒙去世后他由扶余南来继位，传世叙事记其迁都国内城、巩固新政权；其后由子大武神王承统。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/琉璃明王"},{"label":"《三国史记·高句丽国本纪》（中国哲学书电子化计划）","url":"https://ctext.org/wiki.pl?chapter=285115&if=en&remap=gb"}]',NULL,NULL,'琉璃明王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('mangsong-mangtsen','芒松芒赞','tubo','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','吐蕃赞普，松赞干布之孙，幼年即位。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/芒松芒赞"}]',NULL,NULL,'赞普','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('meichuan-wang','美川王','gaogouli','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','美川王名乙弗，故国原王之父。其在位期间高句丽攻取乐浪、带方郡等汉郡故地，势力扩展至大同江流域；死后由故国原王继位。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/美川王"},{"label":"《三国史记·高句丽国本纪》（中国哲学书电子化计划）","url":"https://ctext.org/wiki.pl?chapter=285115&if=en&remap=gb"}]',NULL,NULL,'美川王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('minzhong-wang','闵中王','gaogouli','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','高句丽君主，名解色朱，大武神王之弟，太子年幼时被推举继位。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/閔中王"}]',NULL,NULL,'闵中王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('mo-yanchuo','磨延啜','huihu','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["可汗","君主"]','骨力裴罗之子，唐封英武可汗。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/磨延啜"}]',NULL,NULL,'英武可汗','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('mu-ne-btsan','穆尼赞普','tubo','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','吐蕃赞普，亦称木奈赞普，在位极短。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/穆尼赞普"}]',NULL,NULL,'赞普','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('muben-wang','慕本王','gaogouli','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','慕本王名解忧，为大武神王之子。传世记载称他施政暴虐，后来被侍从杜鲁杀死；王室随即推举大武神王之弟闵中王继位。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/慕本王"},{"label":"《三国史记·高句丽国本纪》（中国哲学书电子化计划）","url":"https://ctext.org/wiki.pl?chapter=285115&if=en&remap=gb"}]',NULL,NULL,'慕本王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('mugui','慕璝','tuyuhun','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','慕璝是阿豺之弟，阿豺死后继位。刘宋与北魏均曾授予其封号；他与夏、北魏及南朝交涉，使吐谷浑在北方政权竞争中维持独立。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/慕璝"},{"label":"《旧唐书·吐谷浑传》研究所引史料（山西大学学位论文）","url":"https://ygx.sxu.edu.cn/db/学位/D01117545.pdf"}]','陇西王',NULL,'惠王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('muliyan','慕利延','tuyuhun','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','慕利延为慕璝之弟，慕璝死后统领吐谷浑。北魏太武帝进军后，他率部西徙，后又返回故地；其经历显示北魏扩张对吐谷浑政治中心的持续压力。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/慕利延"},{"label":"《旧唐书·吐谷浑传》研究所引史料（山西大学学位论文）","url":"https://ygx.sxu.edu.cn/db/学位/D01117545.pdf"}]',NULL,NULL,'河南王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('murong-shun','慕容顺','tuyuhun','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','甘豆可汗，伏允之子，唐册封西平郡王。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/慕容顺"}]',NULL,NULL,'甘豆可汗','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('murong-tuyuhun','慕容吐谷浑','tuyuhun','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','鲜卑首领慕容涉归之子、慕容廆之兄，承领父亲分给的部众。传世记载称兄弟因马群争牧失和，他于西晋时期率部离开辽东，先居阴山，后南下陇西及青海一带，形成独立部族势力。其后裔继续扩张，吐谷浑成为部族与政权名称；出走缘由带有传统叙事色彩。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/慕容吐谷浑"},{"label":"《旧唐书·吐谷浑传》研究所引史料（山西大学学位论文）","url":"https://ygx.sxu.edu.cn/db/学位/D01117545.pdf"}]',NULL,NULL,'河南王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('namri-songtsen','南日松赞','tubo','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','南日松赞是松赞干布之父，传统记载称其统一雅隆河谷诸部并向周边扩张。他被部下毒杀后松赞干布继位，吐蕃由此进入快速扩张阶段。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/南日松赞"},{"label":"《新唐书·吐蕃传》（中国哲学书电子化计划）","url":"https://ctext.org/wiki.pl?chapter=496263&if=gb&remap=gb"}]',NULL,NULL,'赞普','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('nuohabo','慕容诺曷钵','tuyuhun','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','慕容诺曷钵为吐谷浑末代可汗，幼年继位，唐廷以弘化公主与其联姻。吐蕃扩张迫使其在663年前后率部入唐，吐谷浑王国由此失去故地。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/慕容诺曷钵"},{"label":"《旧唐书·吐谷浑传》研究所引史料（山西大学学位论文）","url":"https://ygx.sxu.edu.cn/db/学位/D01117545.pdf"}]','河源郡王',NULL,'勤豆可汗','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('pingyuan-wang','平原王','gaogouli','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','平原王名阳成，为阳原王之子。其在位时期高句丽面对北齐、隋等北方政权更迭；隋统一后双方关系转为战争，死后由婴阳王继位。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/平原王"},{"label":"《三国史记·高句丽国本纪》（中国哲学书电子化计划）","url":"https://ctext.org/wiki.pl?chapter=285115&if=en&remap=gb"}]',NULL,NULL,'平原王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('rongliu-wang','荣留王','gaogouli','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','荣留王名建武，为婴阳王之弟。唐统一后高句丽与唐关系紧张；642年渊盖苏文发动政变杀荣留王，改立宝藏王，朝廷权力转入其手。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/荣留王"},{"label":"《三国史记·高句丽国本纪》（中国哲学书电子化计划）","url":"https://ctext.org/wiki.pl?chapter=285115&if=en&remap=gb"}]',NULL,NULL,'荣留王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('shanshang-wang','山上王','gaogouli','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','山上王名延优，为故国川王之弟。兄长死后，他在王位争夺中胜出；在位时期修筑丸都城并处理王室继承，之后由其子东川王承统。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/山上王"},{"label":"《三国史记·高句丽国本纪》（中国哲学书电子化计划）","url":"https://ctext.org/wiki.pl?chapter=285115&if=en&remap=gb"}]',NULL,NULL,'山上王','[]');
