INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('shilian','视连','tuyuhun','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','白兰王，臣服西秦。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/视连"}]',NULL,NULL,'白兰王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('shipi','视罴','tuyuhun','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','吐谷浑王，继续据守青海。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/视罴"}]',NULL,NULL,'吐谷浑王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('shiyin','拾寅','tuyuhun','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','拾寅统治时期接受北魏授予的西平王等名号，同时保持吐谷浑首领地位。北魏与吐谷浑围绕青海通道和边境控制多次交涉，其在位时两方关系反复。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/拾寅"},{"label":"《旧唐书·吐谷浑传》研究所引史料（山西大学学位论文）","url":"https://ygx.sxu.edu.cn/db/学位/D01117545.pdf"}]','西平王',NULL,'河南王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('shulogan','树洛干','tuyuhun','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','戊寅可汗，武王，吐谷浑重要君主。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/树洛干"}]','武王',NULL,'戊寅可汗','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('songtsen-gampo','松赞干布','tubo','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','南日松赞之子，7世纪前期继位。父亲遇害、各地反叛后，在大臣支持下平定反对势力，继承雅隆地区基础并向周边扩张，以逻些为统治中心，推动吐蕃整合。641年迎娶唐朝文成公主；藏文创制与佛教传播等事迹也见于其统治时期的传统记载，650年去世。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/松赞干布"},{"label":"《新唐书·吐蕃传》（中国哲学书电子化计划）","url":"https://ctext.org/wiki.pl?chapter=496263&if=gb&remap=gb"}]',NULL,NULL,'赞普','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('suixi','碎奚','tuyuhun','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','吐谷浑王，向前秦称臣。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/碎奚"}]',NULL,NULL,'吐谷浑王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('taizu-wang','太祖王','gaogouli','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','太祖王名宫，传世世系称其为朱蒙后裔，统治时间很长。高句丽史书将其时期与对东沃沮及周边部落的扩张相联系，具体早年纪年存在史料差异。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/太祖王"},{"label":"《三国史记·高句丽国本纪》（中国哲学书电子化计划）","url":"https://ctext.org/wiki.pl?chapter=285115&if=en&remap=gb"}]',NULL,NULL,'太祖王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('tri-desong-btsan','赤德松赞','tubo','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','吐蕃赞普，穆尼赞普之弟，继续推行佛教。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/赤德松赞"}]',NULL,NULL,'赞普','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('tri-detsug-nyima','赤德祖赞','tubo','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','赤德祖赞又称弃隶缩赞，七岁继位，吐蕃大臣摄政。其统治期与唐长期争夺河西、陇右；后与唐和亲，金城公主入藏。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/赤德祖赞"},{"label":"《新唐书·吐蕃传》（中国哲学书电子化计划）","url":"https://ctext.org/wiki.pl?chapter=496263&if=gb&remap=gb"}]',NULL,NULL,'赞普','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('tri-song-detsen','赤松德赞','tubo','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','赤松德赞在位时吐蕃势力强盛，曾攻入长安；他支持佛教传播并推动桑耶寺建成。唐蕃双方后以盟誓与会盟碑确认边界和和平关系。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/赤松德赞"},{"label":"《新唐书·吐蕃传》（中国哲学书电子化计划）","url":"https://ctext.org/wiki.pl?chapter=496263&if=gb&remap=gb"}]',NULL,NULL,'赞普','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('tri-tsug-lde-btsan','赤祖德赞','tubo','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','赤祖德赞又称可黎可足，年号彝泰，推行佛教并与唐维持会盟关系。其死后吐蕃发生反佛运动，传统记载称其被反佛势力杀害。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/赤祖德赞"},{"label":"《新唐书·吐蕃传》（中国哲学书电子化计划）","url":"https://ctext.org/wiki.pl?chapter=496263&if=gb&remap=gb"}]',NULL,NULL,'赞普','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('tuyan','吐延','tuyuhun','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','吐延是慕容吐谷浑之子，继父统领部众。传世史书称他遭仇家刺伤、临终命子叶延迁往白兰；有关故事反映吐谷浑早期向青海发展的传统记忆。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/吐延"},{"label":"《旧唐书·吐谷浑传》研究所引史料（山西大学学位论文）","url":"https://ygx.sxu.edu.cn/db/学位/D01117545.pdf"}]',NULL,NULL,'河南王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('wenzhi-wang','文咨王','gaogouli','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','文咨王名罗云，是长寿王之孙。其承接高句丽南进后的版图，继续与百济、新罗争夺汉江流域；在位后由安藏王继承。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/文咨王"},{"label":"《三国史记·高句丽国本纪》（中国哲学书电子化计划）","url":"https://ctext.org/wiki.pl?chapter=285115&if=en&remap=gb"}]',NULL,NULL,'文咨王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('wuheti','乌纥提','tuyuhun','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','大单于，吐谷浑中期君主。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/乌纥提"}]',NULL,NULL,'大单于','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('wujie-kehan','乌希特勤','huihu','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["可汗","君主"]','亦称乌介特勤，840年南逃，唐封乌介可汗，846年被杀。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/乌介可汗"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('xiaoshoulin-wang','小兽林王','gaogouli','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','小兽林王名丘夫，为故国原王之子。其在位初年接连颁布律令、设太学并引入佛教，重建父王战死后受损的国家秩序；死后由弟故国壤王继位。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/小兽林王"},{"label":"《三国史记·高句丽国本纪》（中国哲学书电子化计划）","url":"https://ctext.org/wiki.pl?chapter=285115&if=en&remap=gb"}]',NULL,NULL,'小兽林王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('xichuan-wang','西川王','gaogouli','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','西川王名药卢，为中川王之子。其在位期间高句丽继续经营北方边境；死后由侄烽上王继位，王位转入故国原王一支。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/西川王"},{"label":"《三国史记·高句丽国本纪》（中国哲学书电子化计划）","url":"https://ctext.org/wiki.pl?chapter=285115&if=en&remap=gb"}]',NULL,NULL,'西川王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('xingda-wang','新大王','gaogouli','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','高句丽君主，名伯固，新大王时期。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/新大王"}]',NULL,NULL,'新大王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('ya-yanchuo','移地健','huihu','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["可汗","君主"]','药罗葛氏，磨延啜次子，唐封英义可汗，后世常称牟羽可汗，引入摩尼教为国教。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/牟羽可汗"}]',NULL,NULL,'英义可汗','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yangyuan-wang','阳原王','gaogouli','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','阳原王名平成，为安原王之子。其统治时期高句丽与新罗、百济反复争夺汉江以北地区；北齐军曾攻至辽东，显示其面对多线压力。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/阳原王"},{"label":"《三国史记·高句丽国本纪》（中国哲学书电子化计划）","url":"https://ctext.org/wiki.pl?chapter=285115&if=en&remap=gb"}]',NULL,NULL,'阳原王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yeyan','叶延','tuyuhun','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','329年确立吐谷浑国号，以父名为氏。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/叶延"}]',NULL,NULL,'吐谷浑王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yingyang-wang','婴阳王','gaogouli','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','婴阳王名元，为平原王之子。隋文帝、隋炀帝先后对高句丽用兵；他命乙支文德迎战，隋军在萨水惨败，成为隋朝国势衰退的重要节点。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/婴阳王"},{"label":"《三国史记·高句丽国本纪》（中国哲学书电子化计划）","url":"https://ctext.org/wiki.pl?chapter=285115&if=en&remap=gb"}]',NULL,NULL,'婴阳王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zhongchuan-wang','中川王','gaogouli','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','中川王名然弗，为东川王之子。继位后高句丽与魏的直接军事压力有所缓和；传世本纪记其处理宫廷争端与边境战事，死后由西川王继位。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/中川王"},{"label":"《三国史记·高句丽国本纪》（中国哲学书电子化计划）","url":"https://ctext.org/wiki.pl?chapter=285115&if=en&remap=gb"}]',NULL,NULL,'中川王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zhongjing-kehan','曷萨特勤','huihu','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["可汗","君主"]','硖跌氏，崇德可汗之弟，唐封昭礼可汗。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/昭礼可汗"}]',NULL,NULL,'昭礼可汗','[]');
